bool _keepEntityCard(Object? element) =>
    element is! Map<String, Object?> ||
    wireKnown(element['kind'], _knownEntityCardKind);

bool _keepSchedule(Object? element) =>
    element is! Map<String, Object?> ||
    wireKnown(element['kind'], _knownScheduleKind);

