  'identity',
  'releases',
  'group-art',
  'artist-art',
  'album-art',
  'lyrics',
  'track-fields',
  'book-fields',
  'album-fields',
};

const _knownEntityCardKind = {
  'album',
  'artist',
  'release-group',
  'playlist',
  'podcast',
  'book',
};

const _knownOrganizeBatchKind = {'organize', 'organize-undo'};

const _knownOrganizeHoldCode = {
  'collision',
  'occupied',
  'occupied-case',
  'untagged',
  'missing',
  'virtual',
  'book-held',
  'read-only',
  'moved-since',
  'uncataloged',
};

const _knownScheduleKind = {'scan', 'backup', 'prune', 'analyze', 'enrich'};
